fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (i, &value) in nums.iter().enumerate() {
        if value == target {
            // Safe to cast because the problem guarantees
            // nums.len() < i32::MAX
            return i as i32;
        }
    }
    // Target not found
    -1
}

